lambda.dangling.code:
std::function<int()> makeCounterBroken() {
    int count = 0;
    return [&count] { return ++count; };  // BUG: count dies when we return
}

std::function<int()> makeCounterFixed() {
    int count = 0;
    return [count]() mutable { return ++count; };  // the lambda keeps its own copy
}

void danglingDemo() {
    auto broken = makeCounterBroken();  // holds a reference to a DEAD variable
    // broken();  // undefined behaviour: garbage, a crash, or "works" today and fails later
    auto fixed = makeCounterFixed();
    out << fixed() << ' ' << fixed() << '\n';  // "1 2"
}

