mem.weak_ptr.code:
struct Hero {
    int id = 0;
    std::shared_ptr<Hero> ally;  // owning link
    std::weak_ptr<Hero> rival;   // NON-owning link
};

void weakPtrDemo() {
    {
        auto a = std::make_shared<Hero>();
        auto b = std::make_shared<Hero>();
        a->id = 1;
        b->id = 2;
        a->ally = b;  // b now has 2 owners
        b->rival = a;  // weak: a still has just 1 owner
        // If rival were a shared_ptr, a and b would own each other.
        // Their counts could never reach 0, so neither would ever be freed: a leak.
    }  // a's count hits 0, a is freed, which releases b, so b is freed too
}

pattern.prefix_sums.code:
std::vector<int> prefixSums(const std::vector<int>& a, Recorder& rec) {
    std::vector<int> prefix(a.size() + 1, 0);  // prefix[i] = sum of the first i values
    for (std::size_t i = 0; i < a.size(); ++i) {
        prefix[i + 1] = prefix[i] + a[i];
    }
    return prefix;
}

// Sum of a[l..r] = (sum of first r+1 values) - (sum of first l values).
int rangeSum(const std::vector<int>& prefix, int l, int r) {
    return prefix[r + 1] - prefix[l];  // O(1), no loop!
}

pattern.sliding_window.code:
int maxWindowSum(const std::vector<int>& a, int k, Recorder& rec) {
    int windowSum = 0;
    for (int i = 0; i < k; ++i) windowSum += a[i];  // the first window
    int best = windowSum;
    for (int right = k; right < static_cast<int>(a.size()); ++right) {
        windowSum += a[right] - a[right - k];  // add the new value, drop the old one
        best = std::max(best, windowSum);
    }
    return best;
}

pattern.two_pointers.code:
std::pair<int, int> pairWithSum(const std::vector<int>& a, int target, Recorder& rec) {
    int left = 0;
    int right = static_cast<int>(a.size()) - 1;
    while (left < right) {
        int sum = a[left] + a[right];
        if (sum == target) return {left, right};
        if (sum < target) ++left;  // need a bigger sum
        else --right;              // need a smaller sum
    }
    return {-1, -1};
}

search.binary.code:
int binarySearch(const std::vector<int>& a, int target, Recorder& rec) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // same as (lo+hi)/2 but cannot overflow
        if (a[mid] == target) {
            return mid;
        }
        if (a[mid] < target) {
            lo = mid + 1;  // target is bigger: throw away the left half
        } else {
            hi = mid - 1;  // target is smaller: throw away the right half
        }
    }
    return -1;
}

