int linearSearch(const std::vector<int>& a, int target, Recorder& rec) {
    for (std::size_t i = 0; i < a.size(); ++i) {
        if (a[i] == target) return static_cast<int>(i);
    }
    return -1;
}

sort.bubble.code:
void bubbleSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t pass = 0; pass + 1 < n; ++pass) {
        bool swapped = false;
        for (std::size_t j = 0; j + 1 < n - pass; ++j) {
            if (a[j] > a[j + 1]) {
                std::swap(a[j], a[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;  // nothing moved: already sorted
    }
}

sort.heap.code:
// Push a[root] down until both children are smaller (max-heap rule).
void siftDown(std::vector<int>& a, std::size_t root, std::size_t size, Recorder& rec) {
    while (true) {
        std::size_t largest = root;
        std::size_t left = 2 * root + 1, right = 2 * root + 2;
        if (left < size && a[left] > a[largest]) largest = left;
        if (right < size && a[right] > a[largest]) largest = right;
        if (largest == root) return;
        std::swap(a[root], a[largest]);
        root = largest;
    }
}

void heapSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t i = n / 2; i-- > 0;) siftDown(a, i, n, rec);
    for (std::size_t end = n; end-- > 1;) {
        std::swap(a[0], a[end]);  // biggest goes to the back
        siftDown(a, 0, end, rec);
    }
}

sort.insertion.code:
void insertionSort(std::vector<int>& a, Recorder& rec) {
    for (std::size_t i = 1; i < a.size(); ++i) {
        int key = a[i];  // the card we are inserting
        std::size_t j = i;
        while (j > 0 && a[j - 1] > key) {
            a[j] = a[j - 1];  // shift the bigger one right
            --j;
        }
        a[j] = key;  // drop the card into the gap
    }
}

sort.merge.code:
// Sorts a[lo, hi)  ("hi" is one past the end, like end() in the STL).
void mergeSort(std::vector<int>& a, std::size_t lo, std::size_t hi, std::vector<int>& tmp,
               Recorder& rec) {
    if (hi - lo < 2) return;  // 0 or 1 items: already sorted
    std::size_t mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid, tmp, rec);  // sort the left half
    mergeSort(a, mid, hi, tmp, rec);  // sort the right half

    std::size_t i = lo, j = mid, k = lo;  // merge two sorted halves
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i < mid) tmp[k++] = a[i++];  // copy leftovers
    while (j < hi) tmp[k++] = a[j++];
    std::copy(tmp.begin() + lo, tmp.begin() + hi, a.begin() + lo);
}

void mergeSort(std::vector<int>& a, Recorder& rec) {
    std::vector<int> tmp(a.size());  // one buffer, reused by every merge
    mergeSort(a, 0, a.size(), tmp, rec);
}

sort.quick.code:
// Lomuto partition: the last element is the pivot.
int partition(std::vector<int>& a, int lo, int hi, Recorder& rec) {
    int pivot = a[hi];
    int store = lo;     // next slot for a value smaller than the pivot
    for (int j = lo; j < hi; ++j) {
        if (a[j] < pivot) {
            std::swap(a[store], a[j]);
            ++store;
        }
    }
    std::swap(a[store], a[hi]);  // pivot lands in its final place
    return store;
}

void quickSort(std::vector<int>& a, int lo, int hi, Recorder& rec) {
    if (lo >= hi) return;
    int p = partition(a, lo, hi, rec);
    quickSort(a, lo, p - 1, rec);  // left of the pivot
    quickSort(a, p + 1, hi, rec);  // right of the pivot
}

void quickSort(std::vector<int>& a, Recorder& rec) {
    quickSort(a, 0, static_cast<int>(a.size()) - 1, rec);
}

sort.selection.code:
void selectionSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t i = 0; i + 1 < n; ++i) {
        std::size_t minIdx = i;  // best candidate so far
        for (std::size_t j = i + 1; j < n; ++j) {
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        std::swap(a[i], a[minIdx]);  // put the smallest in place
    }
}

stack.balanced.code:
bool isBalanced(const std::string& text, Recorder& rec) {
    std::vector<char> stack;  // a vector makes a perfect stack: push_back / back / pop_back
    for (std::size_t i = 0; i < text.size(); ++i) {
        char c = text[i];
        if (c == '(' || c == '[' || c == '{') {
            stack.push_back(c);  // remember the opener
        } else if (c == ')' || c == ']' || c == '}') {
            if (stack.empty()) return false;  // a closer with nothing open
            char open = stack.back();
            stack.pop_back();
            bool match = (open == '(' && c == ')') || (open == '[' && c == ']') ||
                         (open == '{' && c == '}');
            if (!match) return false;
        }
    }
    return stack.empty();  // leftovers mean something was never closed
}
